#!/usr/bin/env node
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { mealTitleBySlug } from "../src/lib/meal-catalog-media.js";

const root = fileURLToPath(new URL("../", import.meta.url));
const titles = mealTitleBySlug(join(root, "catalog"));
const lines = [
  "/** Generated by scripts/generate-meal-media-manifest.mjs — do not hand-edit. */",
  "(function () {",
  "  window.FlavorWeaveMealManifest = " + JSON.stringify(titles, null, 2) + ";",
  "})();",
  "",
];
writeFileSync(new URL("../public/meal-media-manifest.js", import.meta.url), lines.join("\n"));
console.log(`Wrote meal-media-manifest.js (${Object.keys(titles).length} meals).`);
